function icon(name){return `<svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||''}</svg>`}
let page="Market", marketTab="Overview", portfolioTab="Holdings", portfolioEditorOpen=false, researchTab="Overview", hunterData=null, hunterFilter="All", lastResearchTicker="NVDA", researchDetailActive=false, researchReturnPage="Research", researchReturnScrollY=0, researchChartRange="1y", researchRequestSeq=0, settingsFocusUpdates=false;
let hunterAdvancedOpen=false, hunterExpanded=new Set();
let hunterSearch="", hunterSort={key:"setup_rank",dir:"desc"}, hunterMinOpportunity=0, hunterMaxRisk=100, hunterSector="All";
let renderGeneration=0, marketRequestSeq=0;
const viewActive=seq=>seq===renderGeneration;
const chartRequestVersions=new WeakMap();
const chartHistoryCache=new Map();
function chartHistoryFor(ticker,range,fallback){
  if(range==='1y')return fallback;
  return chartHistoryCache.get(`${ticker}:${range}`)||fallback;
}
function cacheChartHistory(ticker,range,history){
  const key=`${ticker}:${range}`;
  chartHistoryCache.delete(key);
  chartHistoryCache.set(key,history);
  if(chartHistoryCache.size>12)chartHistoryCache.delete(chartHistoryCache.keys().next().value);
}
let chartOverlayState={volume:true,sma20:true,sma50:false,sma200:false,support:true,resistance:true,entry:true,risk:true,target:false,events:true};

function openResearchTicker(ticker,originPage=page){
  const t=String(ticker||'').trim().toUpperCase();if(!t)return;
  const origin=researchDetailActive&&page==='Research'?researchReturnPage:originPage;
  if(lastResearchTicker!==t)researchChartRange='1y';
  lastResearchTicker=t;researchReturnPage=origin||'Research';
  researchReturnScrollY=window.scrollY||document.documentElement.scrollTop||0;
  researchDetailActive=true;researchTab='Overview';page='Research';nav();render();window.scrollTo(0,0);
}
function returnFromResearch(){
  ++researchRequestSeq;
  const target=NAV.includes(researchReturnPage)?researchReturnPage:'Research',y=researchReturnScrollY;
  researchDetailActive=false;page=target;nav();render();
  if(target!=='Research')setTimeout(()=>window.scrollTo({top:y,behavior:'auto'}),0);
}
async function api(path,opt={}){const r=await fetch(path,{headers:{"Content-Type":"application/json",...(opt.headers||{})},...opt});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);return d}
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function money(v,compact=false){if(v==null||Number.isNaN(Number(v)))return"—";let n=Number(v);if(compact&&Math.abs(n)>=1e9)return"$"+(n/1e9).toFixed(2)+"B";if(compact&&Math.abs(n)>=1e6)return"$"+(n/1e6).toFixed(1)+"M";return"$"+n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}
function number(v,compact=false){if(v==null||Number.isNaN(Number(v)))return"—";let n=Number(v);if(compact&&Math.abs(n)>=1e12)return(n/1e12).toFixed(2)+"T";if(compact&&Math.abs(n)>=1e9)return(n/1e9).toFixed(2)+"B";if(compact&&Math.abs(n)>=1e6)return(n/1e6).toFixed(1)+"M";return n.toLocaleString(undefined,{maximumFractionDigits:2})}
function pct(v,digits=2){if(v==null||Number.isNaN(Number(v)))return"—";let n=Number(v);return`<span class="${n>=0?'good':'bad'}">${n>=0?'+':''}${n.toFixed(digits)}%</span>`}
function clsRisk(v){return v>=70?'bad':v>=45?'warn':'good'}
function timeText(v){if(!v)return"—";try{return new Date(v).toLocaleString()}catch{return v}}
function rangeText(v){return Array.isArray(v)?`${money(v[0])} – ${money(v[1])}`:money(v)}
function statusClass(s=""){s=s.toUpperCase();return s.includes("EXIT")||s.includes("CRITICAL")||s.includes("HIGH RISK")||s.includes("RISK-OFF")||s.includes("HIGH VOLATILITY")?'danger':s.includes("WATCH")||s.includes("WAIT")||s.includes("REDUCE")||s.includes("CAUTIOUS")||s.includes("EARNINGS")?'warn':'high'}

let updatePollTimer=null, updateLastStatus=null;
function renderUpdateState(d){
    if(!d)return;
    updateLastStatus=d;
    const notice=$('#updateNotice');
    if(notice){
        notice.style.display=(d.status==='available'||d.status==='ready')?'inline-flex':'none';
        notice.textContent=d.status==='ready'?'RESTART TO UPDATE':'UPDATE AVAILABLE';
    }
    const info=$('#updateStatus');
    if(info){
        info.textContent=d.message||'Update status unavailable';
        info.className=(d.status==='error')?'bad':'tiny';
    }
    const details=$('#updateDetails');
    if(details){
        const revision=d.latest_sha?' · Latest: '+d.latest_sha:'';
        details.textContent='Installed '+(d.installed_version||($('#versionBadge')?.textContent||'version unknown'))+revision+
            (d.changed?.length?' · Changed: '+d.changed.join(', '):'');
    }
    const progress=$('#updateProgress');
    if(progress){
        progress.style.display=d.status==='downloading'?'block':'none';
        progress.value=Math.max(0,Math.min(100,Number(d.percent)||0));
    }
    const download=$('#downloadUpdate');
    if(download)download.style.display=d.status==='available'?'inline-flex':'none';
    const apply=$('#applyUpdate');
    if(apply)apply.style.display=d.status==='ready'?'inline-flex':'none';
    const result=$('#previousUpdateResult');
    if(result)result.textContent=d.last_result?.message?
        ('Previous update: '+d.last_result.message):'';
}
async function refreshUpdateState(){
    try{renderUpdateState(await api('/api/updates/status'))}catch(e){
        renderUpdateState({status:'error',message:e.message});
    }
}
async function checkGithubUpdates(force=false){
    try{
        const suffix=force?'?force=1':'';
        renderUpdateState(await api('/api/updates/check'+suffix));
    }catch(e){renderUpdateState({status:'error',message:e.message})}
}
function bindUpdateControls(){
    const btn=$('#checkUpdates');
    if(btn)btn.onclick=()=>checkGithubUpdates(true);
    const download=$('#downloadUpdate');
    if(download)download.onclick=async()=>{
        download.disabled=true;
        try{
            renderUpdateState(await api('/api/updates/download',
                                      {method:'POST',body:'{}'}));
        }catch(e){renderUpdateState({status:'error',message:e.message})}
        finally{download.disabled=false}
    };
    const apply=$('#applyUpdate');
    if(apply)apply.onclick=async()=>{
        apply.disabled=true;
        try{
            await api('/api/updates/apply',{method:'POST',body:'{}'});
            const info=$('#updateStatus');
            if(info)info.textContent='Installing verified update and restarting the application…';
            watchUpdateRestart();
        }catch(e){
            renderUpdateState({status:'error',message:e.message});
            apply.disabled=false;
        }
    };
    renderUpdateState(updateLastStatus);
}
function watchUpdateRestart(){
    let wasDown=false;
    let elapsed=0;
    const started=Date.now();
    const timer=setInterval(async()=>{
        elapsed+=1;
        if(elapsed>90){clearInterval(timer);return}
        try{
            await api('/api/health');
            const state=await api('/api/updates/status');
            const finished=state.last_result && Date.parse(state.last_result.time)>=started-1000;
            if(wasDown||finished){clearInterval(timer);window.location.reload()}
        }catch(e){wasDown=true}
    },1000);
}
function startUpdateChecks(){
    setTimeout(()=>checkGithubUpdates(false),1800);
    updatePollTimer=setInterval(()=>refreshUpdateState(),3500);
    setInterval(()=>checkGithubUpdates(false),6*60*60*1000);
}

