async function Market(force=false){
  setTitle('Market','Indexes, sector strength, news and market conditions');
  const v=$('#view'),viewSeq=renderGeneration,marketSeq=++marketRequestSeq;
  v.innerHTML=loading('Loading market overview…');
  try{
    const d=await api(force===true?'/api/dashboard?force=1':'/api/dashboard');
    if(!viewActive(viewSeq)||marketSeq!==marketRequestSeq)return;
    const indexes=d.indexes||[],sectors=d.sectors||[],articles=d.news||[];
    const maxSector=Math.max(1,...sectors.map(x=>Math.abs(x.change_percent||0)));
    v.innerHTML=`<div class="section-head"><div><h2>Market snapshot</h2><p>Best-effort sources · retrieved ${timeText(d.updated_at)}</p></div><div class="toolbar"><button class="secondary" id="refreshDash">Refresh data</button><button class="primary" id="quickHunter">Run discovery scan →</button></div></div>
    ${(d.errors||[]).length?`<div class="warning-box">Partial market data: ${d.errors.length} source(s) unavailable.</div>`:''}
    ${indexes.length?`<div class="market-indexes">${indexes.map(x=>`<article class="index-card"><div class="index-head"><span>${esc(x.name)}</span><small>${esc(x.ticker)}</small></div><div class="value">${money(x.price)}</div><div class="index-change">${pct(x.change_percent)}</div><div class="tiny">Observed ${esc(x.observed_at?timeText(x.observed_at):"Unavailable")}</div></article>`).join('')}</div>`:'<div class="empty">No index quotes available. Refresh when the source returns.</div>'}
    <div class="market-grid"><div class="stack"><section class="regime-banner"><div><span class="caption">Market regime</span><b>${esc(d.regime?.label||'UNKNOWN')}</b><p class="tiny">S&P 1-month ${d.regime?.sp500_momentum_1m!=null?pct(d.regime.sp500_momentum_1m):'Unavailable'} · VIX ${d.regime?.vix??'Unavailable'}</p></div><span class="status ${statusClass(d.regime?.label||'')}">Entry adjustment ${d.regime?.entry_adjust??'—'}</span></section>
    ${panel('Sector performance',sectors.length?`<div class="sector-table">${sectors.map(x=>`<div class="sector-row"><div><div class="sector-name">${esc(x.name)}</div><div class="bar"><div class="fill" style="width:${Math.min(100,Math.abs(x.change_percent||0)/maxSector*100)}%"></div></div></div><small>${esc(x.ticker)}</small><strong>${pct(x.change_percent)}</strong></div>`).join('')}</div>`:'<div class="empty">Sector data unavailable.</div>',`<span class="caption">Free price sources</span>`)}</div>
    ${panel('Latest market headlines',newsRows(articles.slice(0,8))+`<div class="panel-action"><button type="button" class="secondary" id="openMarketNews">Search all market news →</button></div>`,`<span class="caption">${articles.length} items · Source dependent</span>`)}</div>`;
    $('#refreshDash').onclick=()=>Market(true);
    $('#quickHunter').onclick=()=>{page='Discover';nav();render(true)};
    $('#openMarketNews').onclick=()=>{marketTab='News';render()};
  }catch(e){if(viewActive(viewSeq)&&marketSeq===marketRequestSeq)v.innerHTML=errorBox(e)}
}

function searchBar(button='ANALYZE',value='NVDA'){return`<form class="searchbar" id="search"><input id="ticker" value="${esc(value)}" placeholder="Ticker, e.g. NVDA"><button class="primary">${button}</button></form>`}
function stockHero(d){let q=d.quote||{},ex=d.exit_risk||{},riskCls=ex.score>=70?'danger':ex.score>=30?'watch':'';return`<section class="panel hero-stock"><div><div class="stock-id"><h2>${esc(q.ticker)}</h2><span>${esc(q.name)}</span></div><div class="stock-price">${money(q.price)} <small>${pct(q.change_percent)}</small></div><div class="stock-meta">${esc(q.exchange||'Exchange unavailable')} · ${esc(q.currency||'USD')} · Updated ${timeText(q.updated_at)}</div></div><div class="exit-badge ${riskCls}"><small>EXIT RISK</small><b>${ex.score??'—'}</b><span>${esc(ex.label||'NORMAL')}</span></div></section>${q.stale?`<div class="warning-box">STALE PRICE · ${timeText(q.updated_at)}. Current decisions unavailable.</div>`:''}`}
function stockMetrics(d){let q=d.quote||{},i=d.indicators||{},p=d.price_model||{},e=d.earnings||{};return`<div class="metric-strip">${metricCard('Day Range',`${money(q.day_low)} – ${money(q.day_high)}`)}${metricCard('52W Range',`${money(q.fifty_two_low)} – ${money(q.fifty_two_high)}`)}${metricCard('RSI 14',i.rsi14!=null?i.rsi14.toFixed(1):'—')}${metricCard('Timing Risk',(p.overextension_risk??safenum(d.scores?.timing_risk))+'/100',esc(p.timing_status||''))}${metricCard('Gap Risk',(i.gap_risk??"—")+'/100',i.current_gap_pct!=null?`${i.current_gap_pct>=0?'+':''}${i.current_gap_pct.toFixed(1)}% latest gap`:'')}${metricCard('Knife Risk',(i.falling_knife_risk??"—")+'/100',`Stabilization ${i.stabilization_score??'—'}/100`)}${metricCard('Earnings',e.available?(e.days_to_earnings>=0?`${e.days_to_earnings}d`:'Passed'):'Unknown',esc(e.risk||'UNKNOWN'))}${metricCard('Room to Resistance',i.room_to_resistance_pct!=null?pct(i.room_to_resistance_pct,1):'—')}</div>`}
function safenum(v){return v==null?'—':Math.round(Number(v))}
function researchPanels(d,showResearch=true){let i=d.indicators||{},p=d.price_model||{},s=d.scores||{},dr=d.score_explanations||{};let timingCls=(p.overextension_risk??0)>=65?'danger':(p.overextension_risk??0)>=45?'warn':'high';let zones=`<div class="research-status"><span class="status ${timingCls}">${esc(p.timing_status||'NEUTRAL')}</span><span class="tiny">Timing risk ${p.overextension_risk??'—'}/100 · Pullback quality ${p.pullback_quality??'—'}/100</span></div><div class="price-zones"><div class="zone"><span>Deep Pullback</span><b>${rangeText(p.strong_buy_zone)}</b></div><div class="zone"><span>Preferred Entry</span><b>${rangeText(p.buy_zone)}</b></div><div class="zone"><span>First Target</span><b>${rangeText(p.take_profit_zone)}</b></div><div class="zone"><span>Risk Exit</span><b>${money(p.risk_exit)}</b></div></div><div class="scenario-row"><div class="scenario"><span>Nearest Support</span><b>${money(p.nearest_support)}</b></div><div class="scenario"><span>First Resistance</span><b>${money(p.first_resistance)}</b></div><div class="scenario"><span>Upside / Downside</span><b>${p.upside_downside_ratio??'—'} : 1</b></div></div><div class="fund-grid" style="margin-top:8px">${fundCard('R/R to Risk Exit',p.risk_reward!=null?p.risk_reward+':1':'—')}${fundCard('Upside to Resistance',p.potential_upside_pct!=null?pct(p.potential_upside_pct,1):'—')}${fundCard('Downside to Support',p.downside_to_support_pct!=null?`${p.downside_to_support_pct.toFixed(1)}%`:'—')}${fundCard('Gap Risk',(p.gap_risk??0)+'/100')}${fundCard('Knife Risk',(p.falling_knife_risk??0)+'/100')}${fundCard('Timing Risk',(p.overextension_risk??'—')+'/100')}</div><p class="tiny" style="margin-top:8px">${esc(p.method||'')} · ${esc(p.warning||'')}</p>`;let scoresHtml=`<div class="score-list">${scoreRow('Opportunity',s.opportunity,false,dr.opportunity)}${scoreRow('Entry',s.entry,false,dr.entry)}${scoreRow('Quality',s.quality,false,dr.quality)}${scoreRow('Momentum',s.momentum,false,dr.momentum)}${scoreRow('Risk',s.risk,true,dr.risk)}${scoreRow('Confidence',s.confidence,false,dr.confidence)}</div>`;let technical=`<div class="fund-grid">${fundCard('SMA 20',money(i.sma20))}${fundCard('SMA 50',money(i.sma50))}${fundCard('SMA 200',money(i.sma200))}${fundCard('ATR 14',money(i.atr14))}${fundCard('1W Momentum',i.momentum_1w!=null?pct(i.momentum_1w,1):'—')}${fundCard('1M Momentum',i.momentum_1m!=null?pct(i.momentum_1m,1):'—')}${fundCard('3M Momentum',i.momentum_3m!=null?pct(i.momentum_3m,1):'—')}${fundCard('20D Volatility',i.volatility20!=null?i.volatility20.toFixed(1)+'%':'—')}${fundCard('Latest Gap',i.current_gap_pct!=null?pct(i.current_gap_pct,1):'—')}${fundCard('Lower Lows 10D',i.lower_lows_10d??'—')}${fundCard('Days Since 20D Low',i.days_since_20d_low??'—')}${fundCard('Stabilization',(i.stabilization_score??'—')+'/100')}</div>`;if(showResearch==='technicals')return `<div class="stack">${panel('Indicators',technical)}${panel('Scores',scoresHtml,'<span class="caption">Higher risk = worse</span>')}</div>`;
const chart=panel('Price chart',miniChart(d.history,d.ticker||d.quote?.ticker||lastResearchTicker,researchChartRange));
const analysis=fold('All scores and drivers',scoresHtml);
return `<div class="stack">${chart}${panel('Price levels',`<div class="price-zones compact-levels"><div class="zone"><span>Entry</span><b>${rangeText(p.buy_zone)}</b></div><div class="zone"><span>Target</span><b>${rangeText(p.take_profit_zone)}</b></div><div class="zone"><span>Risk exit</span><b>${money(p.risk_exit)}</b></div></div><p class="tiny">Model estimates · not orders</p>${fold('All price levels and risk metrics',zones)}`)}${showResearch===false?analysis+fold('Technical indicators',technical):''}</div>`;
}

function hunterValue(r,key){if(key==='ticker')return r.ticker;if(key==='price')return r.price;if(key==='change')return r.change_percent;if(key==='opportunity')return r.scores?.opportunity;if(key==='entry')return r.scores?.entry;if(key==='quality')return r.scores?.quality;if(key==='momentum')return r.scores?.momentum;if(key==='risk')return r.scores?.risk;if(key==='confidence')return r.scores?.confidence;if(key==='volume')return r.indicators?.avg_volume20;if(key==='rr')return r.price_model?.risk_reward;if(key==='setup_rank')return r.setup_rank;if(key==='sector')return r.sector?.sector||'';return 0}
function filteredHunter(){if(!hunterData)return[];let a=[...(hunterData.results||[])];if(hunterFilter==='Momentum')a=a.filter(x=>(x.scores?.momentum??0)>=70);if(hunterFilter==='Quality')a=a.filter(x=>(x.scores?.quality??0)>=65);if(hunterFilter==='Low Risk')a=a.filter(x=>(x.scores?.risk??100)<40);if(hunterFilter==='Strong Setup')a=a.filter(x=>x.status==='STRONG SETUP');if(hunterFilter==='Pullback Watch')a=a.filter(x=>x.status==='WAIT FOR PULLBACK');if(hunterFilter==='Oversold')a=a.filter(x=>(x.indicators?.rsi14??100)<40&&(x.indicators?.falling_knife_risk??100)<55);if(hunterFilter==='High Volume')a=a.filter(x=>(x.indicators?.relative_volume??0)>=1.5);if(hunterSearch)a=a.filter(x=>(x.ticker+' '+(x.name||'')).toLowerCase().includes(hunterSearch.toLowerCase()));a=a.filter(x=>(x.scores?.opportunity??0)>=hunterMinOpportunity&&(x.scores?.risk??100)<=hunterMaxRisk);if(hunterSector!=='All')a=a.filter(x=>(x.sector?.sector||'Broad Market')===hunterSector);let dir=hunterSort.dir==='asc'?1:-1,key=hunterSort.key;a.sort((x,y)=>{let A=hunterValue(x,key),B=hunterValue(y,key);if(typeof A==='string')return A.localeCompare(B)*dir;return ((Number(A)||0)-(Number(B)||0))*dir});return a}
function sortHead(label,key){
  const selected=hunterSort.key===key;
  return `<th scope="col" aria-sort="${selected?(hunterSort.dir==='asc'?'ascending':'descending'):'none'}"><button type="button" data-sort="${key}" class="sort-button">${label}<span aria-hidden="true">${selected?(hunterSort.dir==='asc'?'↑':'↓'):'↕'}</span></button></th>`;
}
function renderHunterTable(){
  const out=$('#hunterResults');if(!out||!hunterData)return;
  const rows=filteredHunter(),sectors=['All',...new Set((hunterData.results||[]).map(x=>x.sector?.sector||'Broad Market'))];
  const freshControls=!out.querySelector('.hunter-controls');
  if(freshControls)out.innerHTML=`<div class="hunter-controls"><div class="filterbar" role="group" aria-label="Quick filters">${['All','Momentum','Quality','Low Risk','Strong Setup','Pullback Watch','Oversold','High Volume'].map(x=>`<button type="button" data-f="${x}" class="${hunterFilter===x?'active':''}" aria-pressed="${hunterFilter===x}">${x}</button>`).join('')}</div>
  <div class="hunter-search-row"><label class="hunter-search-label"><span class="sr-only">Search results</span><input id="hunterSearch" type="search" placeholder="Filter by ticker or company" value="${esc(hunterSearch)}" autocomplete="off"></label><details class="filter-details" id="hunterAdvanced" ${hunterAdvancedOpen?'open':''}><summary>Advanced filters <span aria-hidden="true">⌄</span></summary><div class="hunter-fields"><label>Minimum opportunity<input id="hunterMinOpp" type="number" min="0" max="100" value="${hunterMinOpportunity}"></label><label>Maximum risk<input id="hunterMaxRisk" type="number" min="0" max="100" value="${hunterMaxRisk}"></label><label>Sector<select id="hunterSector">${sectors.map(x=>`<option ${x===hunterSector?'selected':''}>${esc(x)}</option>`).join('')}</select></label></div></details></div></div>
  <div class="hunter-results-body"></div>`;
  const results=$('.hunter-results-body',out);
  results.innerHTML=`<div class="results-toolbar"><span>${rows.length} / ${(hunterData.results||[]).length} matches</span></div>
  ${rows.length?`<div class="table-wrap hunter-table-wrap"><table><thead><tr>${sortHead('Stock','ticker')}${sortHead('Price','price')}${sortHead('Day','change')}${sortHead('Opportunity','opportunity')}${sortHead('Entry','entry')}${sortHead('Risk','risk')}${sortHead('Setup','setup_rank')}${sortHead('Sector','sector')}<th scope="col">Actions</th></tr></thead><tbody>${rows.map(r=>`<tr class="hunter-row" data-ticker="${esc(r.ticker)}" tabindex="0" title="Open research for ${esc(r.ticker)}"><td><b>${esc(r.ticker)}</b><span class="company">${esc(r.name||'')}</span></td><td class="numeric">${money(r.price)}</td><td class="numeric">${pct(r.change_percent)}</td><td class="numeric"><span class="score-chip">${r.scores?.opportunity??'—'}</span></td><td class="numeric">${r.scores?.entry??'—'}</td><td class="numeric"><span class="score-chip risk">${r.scores?.risk??'—'}</span></td><td><span class="status ${statusClass(r.status)}">${esc(r.status||'UNKNOWN')}</span></td><td>${esc(r.sector?.sector||'Broad Market')}</td><td class="action-cell"><button class="secondary small" data-research="${esc(r.ticker)}" type="button">Research ↗</button><button class="ghost small" type="button" data-details="${esc(r.ticker)}" aria-expanded="${hunterExpanded.has(r.ticker)}">${hunterExpanded.has(r.ticker)?'Less':'Details'}</button></td></tr>
  ${hunterExpanded.has(r.ticker)?`<tr class="hunter-detail"><td colspan="9"><div class="hunter-evidence"><div><span>Quality</span><b>${r.scores?.quality??'—'}</b></div><div><span>Momentum</span><b>${r.scores?.momentum??'—'}</b></div><div><span>Confidence</span><b>${r.scores?.confidence??'—'}</b></div><div><span>Avg volume</span><b>${number(r.indicators?.avg_volume20,true)}</b></div><div><span>Gap risk</span><b>${r.indicators?.gap_risk??'—'}</b></div><div><span>Knife risk</span><b>${r.indicators?.falling_knife_risk??'—'}</b></div><div><span>Risk/reward</span><b>${r.price_model?.risk_reward??'—'}</b></div><p>${esc(r.why||'No additional explanation available.')}</p></div></td></tr>`:''}`).join('')}</tbody></table></div>`:'<div class="empty">No opportunities match these filters. Clear the search or adjust the filters.</div>'}
  ${fold('Scan details',`<p class="tiny">${esc(hunterData.note||'Free data may be delayed.')}</p>${(hunterData.errors||[]).map(e=>`<div class="tiny">${esc(e.ticker)}: ${esc(e.error)}</div>`).join('')}`)}`;
  $$('.filterbar button',out).forEach(b=>{b.classList.toggle('active',b.dataset.f===hunterFilter);b.setAttribute('aria-pressed',String(b.dataset.f===hunterFilter))});
  if(freshControls){
    $$('.filterbar button',out).forEach(b=>b.onclick=()=>{hunterFilter=b.dataset.f;renderHunterTable()});
    $('#hunterSearch').oninput=e=>{hunterSearch=e.target.value;renderHunterTable()};
    $('#hunterAdvanced').ontoggle=e=>{hunterAdvancedOpen=e.target.open};
    $('#hunterMinOpp').onchange=e=>{hunterMinOpportunity=Math.max(0,Math.min(100,Number(e.target.value)||0));renderHunterTable()};
    $('#hunterMaxRisk').onchange=e=>{let n=Number(e.target.value);hunterMaxRisk=Number.isFinite(n)?Math.max(0,Math.min(100,n)):100;renderHunterTable()};
    $('#hunterSector').onchange=e=>{hunterSector=e.target.value;renderHunterTable()};
  }
  $$('[data-sort]',results).forEach(b=>b.onclick=()=>{const k=b.dataset.sort;if(hunterSort.key===k)hunterSort.dir=hunterSort.dir==='asc'?'desc':'asc';else hunterSort={key:k,dir:k==='ticker'||k==='sector'?'asc':'desc'};renderHunterTable()});
  $$('.hunter-row',results).forEach(tr=>{
    tr.onclick=e=>{if(e.target.closest('button'))return;openResearchTicker(tr.dataset.ticker,'Discover')};
    tr.onkeydown=e=>{if(e.target===tr&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openResearchTicker(tr.dataset.ticker,'Discover')}};
  });
  $$('[data-research]',results).forEach(b=>b.onclick=()=>openResearchTicker(b.dataset.research,'Discover'));
  $$('[data-details]',results).forEach(b=>b.onclick=()=>{if(hunterExpanded.has(b.dataset.details))hunterExpanded.delete(b.dataset.details);else hunterExpanded.add(b.dataset.details);renderHunterTable()});
}

function renderHunterSummary(){
  if(!hunterData||!$('#hunterStats'))return;
  const results=hunterData.results||[],scanned=Number(hunterData.scanned)||0;
  $('#hunterStats').innerHTML=`<div class="kpi-row" style="margin-bottom:10px">${metricCard('Scanned',scanned)}${metricCard('Results',results.length)}${metricCard('Unavailable',Math.max(0,scanned-(hunterData.successful??results.length)))}${metricCard('Market',esc(hunterData.regime?.label||'UNKNOWN'))}</div>`;
}
async function Hunter(auto=false){setTitle('Discover','Search and rank stock opportunities by entry quality and downside risk');let v=$('#view'),viewSeq=renderGeneration,hunterSeq=0;v.innerHTML=`<div class="section-head"><div><h2>Opportunity scanner</h2></div><div class="toolbar"><button class="primary" id="runHunter">RUN HUNTER</button></div></div><div id="hunterStats"></div><div id="hunterResults">${hunterData?loading('Rendering cached scan…'):'<div class="empty">Run Hunter to scan the configured stock universe.</div>'}</div>`;async function run(){let seq=++hunterSeq;let b=$('#runHunter');b.disabled=true;$('#hunterResults').innerHTML=loading('Scanning stocks…');try{let scanned=await api('/api/hunter',{method:'POST',body:'{}'});if(!viewActive(viewSeq)||seq!==hunterSeq)return;hunterData=scanned;renderHunterSummary();renderHunterTable()}catch(e){if(viewActive(viewSeq)&&seq===hunterSeq)$('#hunterResults').innerHTML=errorBox(e)}finally{b.disabled=false}}$('#runHunter').onclick=run;if(hunterData){renderHunterSummary();renderHunterTable()}if(auto)run()}

function researchLists(title,items=[]){return`<div class="list-box"><h4>${title}</h4>${items?.length?`<ul class="thesis-list">${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<div class="tiny">No items reported.</div>'}</div>`}
function decisionOverview(d){
  const x=d.decision_layer||{},s=d.scores||{},r=x.market_regime||{},rs=x.relative_strength||{},e=x.earnings||d.earnings||{},p=d.price_model||{};
  const q=x.company_quality??s.quality,entry=x.entry_quality??s.entry;
  const headline=d.core_research?.status||'UNKNOWN';
  const score=(label,value,sub='')=>metricCard(label,value==null?'—':value+'/100',esc(sub));
  const earnings=e.available?(e.days_to_earnings>=0?e.days_to_earnings+'d':'Passed'):'Unknown';
  return `<section class="panel panel-pad decision-summary"><div class="decision-heading"><span class="status ${statusClass(headline)}">${esc(headline)}</span><span class="tiny">${d.core_research?.confidence==null?'Evidence confidence unavailable':esc(d.core_research.confidence)+'% confidence'}</span></div><div class="compact-kpis">${score('Quality',q,x.company_label||'')}${score('Entry',entry,x.entry_label||'')}${score('Opportunity',s.opportunity)}${score('Risk',s.risk)}</div>${fold('Decision factors',`<div class="fund-grid">${fundCard('Market regime',esc(r.label||'UNKNOWN'))}${fundCard('Relative strength',rs.score??'—')}${fundCard('Benchmark',esc(rs.benchmark_name||rs.benchmark||'—'))}${fundCard('Earnings',esc(earnings)+' · '+esc(e.risk||'UNKNOWN'))}${fundCard('Upside/downside',p.upside_downside_ratio==null?'—':p.upside_downside_ratio+':1')}${fundCard('VIX',r.vix??'—')}${fundCard('S&P 1M',r.sp500_momentum_1m==null?'—':pct(r.sp500_momentum_1m))}</div>`)} </section>`;
}
function thesisHealthPanel(d){let th=d.thesis_health||{};if(!th.tracked)return `<div class="empty compact-empty">No structured thesis is tracked for this ticker. Add the position in Portfolio and select the reasons you bought it.</div>`;return `<div class="thesis-health-head"><div><span class="caption">THESIS HEALTH</span><b class="${(th.score??0)>=70?'good':(th.score??0)<45?'bad':'warn'}">${th.score??'—'}/100</b></div><div class="tiny">${th.valid} valid · ${th.invalid} broken · ${th.unknown} unknown</div></div><div class="thesis-checks">${(th.items||[]).map(x=>`<div class="thesis-check ${x.valid===true?'ok':x.valid===false?'broken':'unknown'}"><span>${x.valid===true?'✓':x.valid===false?'✕':'?'}</span><div><b>${esc(x.label)}</b><small>${esc(x.detail)}</small></div></div>`).join('')}</div>`}
function researchHistoryPanel(d){let h=d.research_history||[],chg=d.research_change||{};if(!h.length)return '<div class="empty compact-empty">No previous decision snapshots yet.</div>';let delta=chg.available?`<div class="change-summary"><b>WHAT CHANGED</b><small>${esc(chg.summary||'')}</small><div>${(chg.items||[]).map(x=>`<span class="change-chip ${x.delta>0?'up':'down'}">${esc(x.metric)} ${x.delta>0?'+':''}${x.delta}</span>`).join('')}</div></div>`:'';return delta+`<div class="history-list">${h.map((x,i)=>`<div class="history-row"><div><b>${esc(x.status||'UNKNOWN')}</b><small>${timeText(x.created_at)}</small></div><span>${money(x.price)}</span><span>Opp ${x.opportunity??'—'}</span><span>Entry ${x.entry??'—'}</span><span>Risk ${x.risk??'—'}</span>${i===0?'<em>LATEST</em>':''}</div>`).join('')}</div>`}
function newsEventPanel(d){if(d.news_risk?.available===false)return '<div class="warning-box">News evidence unavailable. Risk impact is UNKNOWN until sources return reliable data.</div>';let ev=d.news_risk?.events||[];if(!ev.length)return '<div class="empty compact-empty">No material news events classified.</div>';return `<div class="event-list">${ev.slice(0,8).map(e=>`<div class="event-row"><div><b>${esc(e.type)}</b><small>${esc(e.title||'')}</small></div><span class="status ${e.confirmation?.includes('UNVERIFIED')?'warn':'high'}">${esc(e.confirmation)}</span><span>${e.outlet_count??0} outlets</span><span class="${(e.risk_points||0)>0?'bad':(e.risk_points||0)<0?'good':''}">${e.risk_points>0?'+':''}${e.risk_points}</span></div>`).join('')}</div>`}

function freshnessPanel(d){let f=d.freshness||{};return `<div class="freshness-grid">${fundCard('PRICE',timeText(f.market))}${fundCard('RESEARCH',timeText(f.research))}${fundCard('NEWS',timeText(f.news))}${fundCard('SEC FISCAL END',esc(f.sec_fiscal_end||'Unavailable'))}${fundCard('LATEST FILING',esc(f.latest_filing||'Unavailable'))}</div><p class="tiny" style="margin-top:8px">Missing or stale evidence reduces confidence instead of being guessed.</p>`}
async function DeepResearch(){
  setTitle('Research','Company evidence, price history and entry discipline');
  const v=$('#view'),viewSeq=renderGeneration;
  if(!researchDetailActive){
    v.innerHTML=`<section class="research-landing panel panel-pad"><h2>Research a stock</h2><p>Enter a ticker to view its chart and analysis.</p>${searchBar('Open research →',lastResearchTicker)}</section>`;
    $('#search').onsubmit=e=>{e.preventDefault();openResearchTicker($('#ticker').value,'Research')};return;
  }
  v.innerHTML=`<div class="section-head research-header"><div><button type="button" class="back-link" id="researchReturn">← Back to ${researchReturnPage==='Research'?'research search':esc(researchReturnPage)}</button><h2>${esc(lastResearchTicker)} · Research</h2></div>${searchBar('Analyze →',lastResearchTicker)}</div><div id="out"></div>`;

function renderFull(d){let f=d.fundamentals||{},c=d.core_research||{},a=d.ai_research||{},src=d.source_summary||{};let fundamentals=`<div class="fund-grid">${fundCard('Revenue',number(f.revenue,true))}${fundCard('Revenue Growth',f.revenue_growth_pct!=null?pct(f.revenue_growth_pct,1):'—')}${fundCard('Net Income',number(f.net_income,true))}${fundCard('NI Growth',f.net_income_growth_pct!=null?pct(f.net_income_growth_pct,1):'—')}${fundCard('Operating Cash Flow',number(f.operating_cashflow,true))}${fundCard('FCF Estimate',number(f.free_cashflow_est,true))}${fundCard('Cash',number(f.cash,true))}${fundCard('Liabilities',number(f.liabilities,true))}</div><p class="tiny" style="margin-top:8px">Source: ${esc(f.source||'SEC unavailable')} · Fiscal end: ${esc(f.latest_fiscal_end||'—')}</p>`;let core=`<div class="research-status"><span class="status ${statusClass(c.status)}">${esc(c.status||'UNKNOWN')}</span><b>${c.confidence==null?'Evidence confidence unavailable':c.confidence+'% evidence confidence'}</b></div><p class="tiny">${esc(c.summary||'')}</p><div class="grid3" style="margin-top:9px">${researchLists('Bull case',c.bull_case)}${researchLists('Bear case',c.bear_case)}${researchLists('Contradicting evidence',c.contradicting_evidence)}</div>`;let ai=`<div id="aiResearchBox"><div class="research-status"><span class="status ${statusClass(a.status)}">${esc(a.status||'OFF')}</span></div><p class="tiny">${esc(a.summary||'')}</p>${a.enabled?'<button class="secondary" id="runAiResearch" style="margin-top:9px">RUN OLLAMA ANALYSIS</button>':''}</div>`;let source=`<div class="fund-grid">${fundCard('SEC Facts',src.sec_available?'AVAILABLE':'UNAVAILABLE')}${fundCard('Primary Filings',src.primary_filings??0)}${fundCard('News Sources',src.news_sources??0)}${fundCard('Primary-Source Confirmed',`${src.confirmed_news_events??0}/${src.news_events??0}`)}</div>${d.stored_thesis?`<div class="list-box" style="margin-top:9px"><h4>Stored position thesis</h4><div class="tiny">${esc(d.stored_thesis)}</div></div>`:''}`;let filings=(d.filings||[]).length?`<div class="table-wrap"><table><thead><tr><th>Form</th><th>Date</th><th>Importance</th><th>Description</th></tr></thead><tbody>${d.filings.map(x=>`<tr><td><a href="${esc(x.url||'#')}" target="_blank" style="color:var(--text)"><b>${esc(x.form)}</b></a></td><td>${esc(x.date||'—')}</td><td><span class="status ${x.importance==='HIGH'?'warn':''}">${esc(x.importance||'')}</span></td><td>${esc(x.description||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No SEC filing metadata available.</div>';$('#out').innerHTML=stockHero(d)+
  `<nav class="research-tabs" aria-label="Research evidence" role="tablist">${['Overview','Financials & SEC','Technicals','News & Events','History'].map(t=>`<button type="button" role="tab" data-research-tab="${t}" aria-selected="${t===researchTab}" class="${t===researchTab?'active':''}">${t}</button>`).join('')}</nav><section id="researchTabContent" role="tabpanel" aria-label="${esc(researchTab)}"></section>`;
function showTab(){
  if(!$('#researchTabContent'))return;
  let content='';
  if(researchTab==='Financials & SEC')content=`<div class="stack">${panel('SEC fundamentals',fundamentals,'<span class="caption">Primary facts</span>')}${panel('SEC filings',filings)}${panel('Evidence coverage',source)}</div>`;
  else if(researchTab==='Technicals')content=stockMetrics(d)+researchPanels(d,'technicals');
  else if(researchTab==='News & Events')content=`<div class="research-columns"><div class="stack">${panel('Event intelligence',newsEventPanel(d),`<span class="caption">Risk ${d.news_risk?.available===false?'UNAVAILABLE':(d.news_risk?.score??0)+'/100'}</span>`)}</div><div class="stack">${panel('Headline feed',newsRows((d.news||[]).slice(0,20)),`<span class="caption">${d.news?.length??0} items</span>`)}</div></div>`;
  else if(researchTab==='History')content=panel('Research decision history',researchHistoryPanel(d));
  else content=`<div class="stack">${decisionOverview(d)}${researchPanels(d,true)}${fold('Research reasoning',`<p>${esc(c.summary||'')}</p><div class="research-reason-grid">${researchLists('Why not buy now',d.decision_layer?.why_not_buy)}${researchLists('What improves the decision',d.decision_layer?.upgrade_conditions)}${researchLists('What invalidates the decision',d.decision_layer?.downgrade_conditions)}${researchLists('Bull case',c.bull_case)}${researchLists('Bear case',c.bear_case)}${researchLists('Contradicting evidence',c.contradicting_evidence)}</div>`)}${fold('Data freshness',freshnessPanel(d))}${d.thesis_health?.tracked?fold('Thesis health',thesisHealthPanel(d)):''}${a.enabled?panel('Optional AI',ai):''}</div>`;
  $('#researchTabContent').innerHTML=content;
  $('#researchTabContent').setAttribute('aria-label',researchTab);
  $$('[data-research-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.researchTab===researchTab);b.setAttribute('aria-selected',String(b.dataset.researchTab===researchTab))});
  if(researchTab==='Overview')mountPriceHistory($('#researchTabContent .price-history-slot'),d.ticker||d.quote?.ticker||lastResearchTicker,d.history||[],researchChartRange,{indicators:d.indicators||{},price_model:d.price_model||{},news:d.news||[],earnings:d.earnings||{}});
  const aiBtn=$('#runAiResearch');if(aiBtn)aiBtn.onclick=async()=>{
    const aiBox=$('#aiResearchBox');aiBtn.disabled=true;aiBtn.textContent='Analyzing…';
    try{const x=await api('/api/ai-research/'+encodeURIComponent(d.ticker),{method:'POST'});if(!aiBox.isConnected)return;aiBox.innerHTML=`<div class="research-status"><span class="status ${statusClass(x.status)}">${esc(x.status||'AI')}</span>${x.model?`<span class="badge">${esc(x.model)}</span>`:''}<b>${x.confidence??0}% confidence</b></div><p class="tiny">${esc(x.summary||'')}</p>${x.bull_case?researchLists('AI bull case',x.bull_case):''}${x.bear_case?researchLists('AI bear case',x.bear_case):''}`}
    catch(e){if(aiBox.isConnected)aiBox.innerHTML=errorBox(e)}
  };
}
$$('[data-research-tab]').forEach(b=>b.onclick=()=>{researchTab=b.dataset.researchTab;showTab()});
showTab();
}

async function run(t){let clean=String(t||'').trim().toUpperCase();if(!clean)return;let seq=++researchRequestSeq;if(lastResearchTicker!==clean)researchChartRange='1y';lastResearchTicker=clean;const heading=$('.research-header h2');if(heading)heading.textContent=clean+' · Research';$('#ticker').value=clean;$('#out').innerHTML=loading('Loading market structure and timing risk…');let fast=null;try{fast=await api('/api/stock/'+encodeURIComponent(clean));if(seq!==researchRequestSeq||!viewActive(viewSeq))return;$('#out').innerHTML=stockHero(fast)+researchPanels(fast,false)+`<div style="margin-top:12px">${loading('Loading research…')}</div>`;mountPriceHistory($('#out .price-history-slot'),fast.ticker||fast.quote?.ticker||clean,fast.history||[],researchChartRange,{indicators:fast.indicators||{},price_model:fast.price_model||{}})}catch(e){if(seq===researchRequestSeq&&viewActive(viewSeq))$('#out').innerHTML=errorBox(e);return}try{let d=await api('/api/research/'+encodeURIComponent(clean),{method:'POST'});if(seq!==researchRequestSeq||!viewActive(viewSeq))return;renderFull(d)}catch(e){if(seq===researchRequestSeq&&viewActive(viewSeq))$('#out').insertAdjacentHTML('beforeend',errorBox(e))}}
$('#researchReturn').onclick=returnFromResearch;$('#search').onsubmit=e=>{e.preventDefault();run($('#ticker').value)};run(lastResearchTicker)}

async function News(){setTitle('News Intelligence','Event-aware current headlines with source reliability, confirmation and duplicate clustering');let v=$('#view'),viewSeq=renderGeneration,newsSeq=0;v.innerHTML=`<div class="section-head"><div><h2>News Search</h2></div><form class="searchbar" id="newsSearch"><input id="newsQuery" value="NVDA" placeholder="NVDA, semiconductors, rates…"><button class="primary">SEARCH NEWS</button></form></div><div id="newsOut"><div class="empty">Search a ticker, company, or topic.</div></div>`;async function run(q){let seq=++newsSeq;$('#newsOut').innerHTML=loading('Searching news…');try{let d=await api('/api/news-search/'+encodeURIComponent(q));if(!viewActive(viewSeq)||seq!==newsSeq)return;let tier=d.items.filter(x=>x.reliability>=85).length,confirmed=d.risk.confirmed_event_count??0,total=d.risk.event_count??0;$('#newsOut').innerHTML=`<div class="kpi-row" style="margin-bottom:12px">${metricCard('Query',esc(d.resolved_query))}${metricCard('Event Risk',d.risk.available===false?'UNAVAILABLE':d.risk.score+'/100')}${metricCard('Primary-Source Confirmed',`${confirmed}/${total}`)}${metricCard('Tier-1 Sources',tier)}</div><div class="grid2">${panel('Event Intelligence',newsEventPanel({news_risk:d.risk}),`<span class="caption">${total} grouped events</span>`)}${panel('Headline Feed',newsRows(d.items),`<span class="updated">${esc(d.provider||'Free news')} · ${timeText(d.updated_at)}</span>`)}</div>`}catch(e){if(viewActive(viewSeq)&&seq===newsSeq)$('#newsOut').innerHTML=errorBox(e)}}$('#newsSearch').onsubmit=e=>{e.preventDefault();let q=$('#newsQuery').value.trim();if(q)run(q)}}

async function Portfolio(){setTitle('Portfolio','Editable lots, grouped holdings, thesis health and position-specific protection');let v=$('#view'),viewSeq=renderGeneration,loadSeq=0;let thesisTags=[['revenue_growth','Revenue growth'],['earnings_growth','Earnings growth'],['positive_fcf','Positive FCF'],['uptrend','Healthy uptrend'],['attractive_entry','Attractive entry'],['low_risk','Controlled risk'],['momentum','Strong momentum'],['catalyst','Positive catalyst']];let editingId=null;v.innerHTML=`<details class="position-editor panel" id="positionEditor" ${portfolioEditorOpen?'open':''}><summary>+ Add or edit a position</summary><form class="panel-pad position-form" id="pos"><input id="pt" placeholder="Ticker"><input id="ps" placeholder="Shares" type="number" step="any"><input id="pa" placeholder="Avg price" type="number" step="any"><input class="wide" id="pth" placeholder="Original thesis — why you bought it"><div class="toolbar"><button class="primary" id="savePos">ADD LOT</button><button class="secondary" type="button" id="cancelEdit" hidden>CANCEL EDIT</button></div><div class="thesis-selector wide"><span class="caption">TRACK THESE BUY REASONS</span><div>${thesisTags.map(([id,label])=>`<label><input type="checkbox" value="${id}" class="thesis-tag"> ${label}</label>`).join('')}</div></div></form></details><div id="out" style="margin-top:12px"></div>`;function reset(){editingId=null;$('#pt').value=$('#ps').value=$('#pa').value=$('#pth').value='';$$('.thesis-tag').forEach(x=>x.checked=false);$('#savePos').textContent='ADD LOT';$('#cancelEdit').hidden=true;portfolioEditorOpen=false;$('#positionEditor').open=false}$('#positionEditor').ontoggle=e=>{portfolioEditorOpen=e.target.open};$('#cancelEdit').onclick=reset;async function load(){let seq=++loadSeq;try{let r=await api('/api/risk');if(!viewActive(viewSeq)||seq!==loadSeq)return;let grouped=r.grouped?.length?`<section class="panel panel-pad"><div class="panel-title"><h3>Grouped Holdings</h3><span class="caption">Multiple lots combined</span></div><div class="grouped-grid">${r.grouped.map(g=>`<div class="grouped-card"><b>${g.ticker}</b><span>${g.lots} lot(s) · ${number(g.shares)} shares</span><strong>${money(g.value)}</strong><small>Weighted avg ${money(g.avg_cost)} · ${g.pnl_percent==null?'UNAVAILABLE':(g.pnl_percent>=0?'+':'')+g.pnl_percent.toFixed(2)+'%'}</small></div>`).join('')}</div></section>`:'';let sectors=r.sector_exposure?.length?`<section class="panel panel-pad"><div class="panel-title"><h3>Sector Exposure</h3></div><div class="sector-exposure">${r.sector_exposure.map(x=>`<div><span>${esc(x.sector)}</span><div class="bar"><div class="fill" style="width:${Math.min(100,x.percent)}%"></div></div><b>${x.percent}%</b></div>`).join('')}</div></section>`:'';let missingBanner=r.valuation_complete?'':`<div class="warning-box">${r.unpriced_lots} lot(s) have unavailable prices. Portfolio totals, P/L, concentration and sector exposure cannot be calculated reliably. Priced subset: ${money(r.priced_market_value)} market value against ${money(r.priced_cost)} cost.</div>`;$('#out').innerHTML=`${missingBanner}<div class="portfolio-summary">${metricCard('Market Value',money(r.total_value))}${metricCard('Cost Basis',money(r.total_cost))}${metricCard('Unrealized P/L',money(r.total_pnl),r.total_pnl_percent!=null?`${r.total_pnl_percent>=0?'+':''}${r.total_pnl_percent.toFixed(2)}%`:'')}${metricCard('Lots',r.positions.length)}${metricCard('Highest Exit Risk',r.positions.length?(r.valuation_complete?Math.max(...r.positions.map(x=>x.exit_risk?.score||0))+'/100':'UNAVAILABLE'):'—')}</div>${(r.warnings||[]).map(w=>`<div class="warning-box">${esc(w.type)}: <b>${esc(w.ticker)}</b> is ${w.percent}% of current portfolio value.</div>`).join('')}<div class="grid2">${grouped}${sectors}</div>${r.positions.length?`<div class="table-wrap"><table><thead><tr><th>Lot</th><th>Sector</th><th>Price / P&L</th><th>Exit Risk</th><th>Thesis Health</th><th>Position Action</th><th>Trailing Exit</th><th>Protection</th><th>Thesis</th><th>Actions</th></tr></thead><tbody>${r.positions.map(p=>`<tr><td><b>${p.ticker}</b><span class="company">${p.shares} sh · avg ${money(p.avg_price)}</span></td><td>${esc(p.sector||'Broad Market')}</td><td>${p.error?'—':`${money(p.price)}<span class="company">${pct(p.pnl_percent)}</span>`}</td><td>${p.error?'<span class="bad">ERROR</span>':`<span class="status ${statusClass(p.exit_risk?.label)}">${p.exit_risk?.score}/100 ${p.exit_risk?.label}</span>`}</td><td>${p.thesis_health?.tracked?`<b class="${(p.thesis_health.score??0)>=70?'good':(p.thesis_health.score??0)<45?'bad':'warn'}">${p.thesis_health.score??'—'}/100</b><span class="company">${p.thesis_health.valid} valid / ${p.thesis_health.invalid} broken</span>`:'<span class="company">Not tracked</span>'}</td><td><span class="status ${statusClass(p.position_strategy?.action||'')}">${esc(p.position_strategy?.action||'—')}</span>${p.position_strategy?.partial_profit_percent?`<span class="company">Partial: ${p.position_strategy.partial_profit_percent}%</span>`:''}</td><td>${money(p.position_strategy?.trailing_exit)}</td><td>${p.position_strategy?.protected_gain_percent>0?`+${p.position_strategy.protected_gain_percent}% above cost`:'—'}</td><td><span class="company">${esc(p.thesis||'—')}</span></td><td><div class="row-actions"><button class="secondary small" data-edit="${p.id}">EDIT</button><button class="danger-btn" data-del="${p.id}">REMOVE</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No positions stored yet.</div>'}`;$$('[data-del]').forEach(b=>b.onclick=async()=>{if(!window.confirm('Remove this saved portfolio lot?'))return;try{await api('/api/positions/'+b.dataset.del,{method:'DELETE'});if(!viewActive(viewSeq))return;if(editingId===Number(b.dataset.del))reset();load()}catch(e){if(viewActive(viewSeq))$('#out').insertAdjacentHTML('afterbegin',errorBox(e))}});$$('[data-edit]').forEach(b=>b.onclick=()=>{let pos=r.positions.find(x=>x.id===Number(b.dataset.edit));if(!pos)return;editingId=pos.id;portfolioEditorOpen=true;$('#positionEditor').open=true;$('#pt').value=pos.ticker;$('#ps').value=pos.shares;$('#pa').value=pos.avg_price;$('#pth').value=pos.thesis||'';let tags=[];try{tags=Array.isArray(pos.thesis_tags)?pos.thesis_tags:JSON.parse(pos.thesis_json||'[]')}catch{}$$('.thesis-tag').forEach(x=>x.checked=tags.includes(x.value));$('#savePos').textContent='SAVE CHANGES';$('#cancelEdit').hidden=false;window.scrollTo({top:0,behavior:'smooth'})})}catch(e){if(viewActive(viewSeq)&&seq===loadSeq)$('#out').innerHTML=errorBox(e)}}$('#pos').onsubmit=async e=>{e.preventDefault();try{let tags=$$('.thesis-tag:checked').map(x=>x.value),body=JSON.stringify({ticker:$('#pt').value,shares:Number($('#ps').value),avg_price:Number($('#pa').value),thesis:$('#pth').value,thesis_tags:tags});if(editingId)await api('/api/positions/'+editingId,{method:'PUT',body});else await api('/api/positions',{method:'POST',body});if(!viewActive(viewSeq))return;reset();load()}catch(x){if(viewActive(viewSeq))$('#out').insertAdjacentHTML('afterbegin',errorBox(x))}};load()}

async function Risk(){setTitle('Risk Monitor','Exit defense, thesis damage and profit protection for every saved position');let v=$('#view'),viewSeq=renderGeneration,riskSeq=0;v.innerHTML=`<div class="section-head"><div><h2>Portfolio Risk Defense</h2></div><button class="primary" id="scanRisk">SCAN PORTFOLIO</button></div><div id="out"></div>`;async function run(){let seq=++riskSeq;let b=$('#scanRisk');b.disabled=true;$('#out').innerHTML=loading('Checking positions…');try{let d=await api('/api/risk');if(!viewActive(viewSeq)||seq!==riskSeq)return;$('#out').innerHTML=(d.positions.length&&!d.valuation_complete?`<div class="warning-box">RISK SCAN INCOMPLETE · ${d.unpriced_lots??0} unpriced lot(s). Current P/L, exposure and exit assessments unavailable.</div>`:'')+(d.warnings||[]).map(w=>`<div class="warning-box">${esc(w.type)}: <b>${esc(w.ticker)}</b> is ${w.percent}% of portfolio value.</div>`).join('')+(d.positions.length?`<div class="risk-cards">${d.positions.map(p=>`<section class="panel risk-card"><div class="risk-head"><div><b>${p.ticker}</b><div class="tiny">${esc(p.thesis||'No stored thesis')}</div></div><span class="status ${statusClass(p.exit_risk?.label)}">${esc(p.exit_risk?.label||'ERROR')}</span></div>${p.error?errorBox(p.error):`<div class="position-decision"><div><span class="caption">POSITION ACTION</span><b>${esc(p.position_strategy?.action||'—')}</b>${p.position_strategy?.partial_profit_percent?`<small>Consider partial profit: ${p.position_strategy.partial_profit_percent}%</small>`:''}</div><div><span class="caption">EXIT RISK</span><b class="${clsRisk(p.exit_risk?.score||0)}">${p.exit_risk?.score??0}/100</b></div></div><div class="fund-grid" style="margin-top:9px">${fundCard('Current',money(p.price))}${fundCard('P/L',p.pnl_percent!=null?pct(p.pnl_percent):'—')}${fundCard('Trailing Exit',money(p.position_strategy?.trailing_exit))}${fundCard('Protected Gain',p.position_strategy?.protected_gain_percent>0?`+${p.position_strategy.protected_gain_percent}%`:'—')}${fundCard('Thesis Health',p.thesis_health?.tracked?(p.thesis_health.score??'—')+'/100':'Not tracked')}${fundCard('News Risk',p.news_risk?.available===false?'UNAVAILABLE':(p.news_risk?.score??0))}${fundCard('Model Risk Exit',money(p.price_model?.risk_exit))}${fundCard('Take Profit',rangeText(p.price_model?.take_profit_zone))}</div>${p.thesis_health?.tracked?`<div class="thesis-checks compact-checks" style="margin-top:9px">${(p.thesis_health.items||[]).map(x=>`<div class="thesis-check ${x.valid===true?'ok':x.valid===false?'broken':'unknown'}"><span>${x.valid===true?'✓':x.valid===false?'✕':'?'}</span><div><b>${esc(x.label)}</b><small>${esc(x.detail)}</small></div></div>`).join('')}</div>`:''}${p.top_risk_news?.length?`<div class="list-box" style="margin-top:9px"><h4>Top risk headlines</h4><ul class="thesis-list">${p.top_risk_news.map(x=>`<li>${esc(x.title)}</li>`).join('')}</ul></div>`:''}`}</section>`).join('')}</div>`:'<div class="empty">Add positions in Portfolio first.</div>')}catch(e){if(viewActive(viewSeq)&&seq===riskSeq)$('#out').innerHTML=errorBox(e)}finally{b.disabled=false}}$('#scanRisk').onclick=run;run()}

async function Alerts(){setTitle('Alerts','Positions that currently require attention');let v=$('#view'),viewSeq=renderGeneration;v.innerHTML=loading('Loading alerts…');try{let d=await api('/api/alerts');if(!viewActive(viewSeq))return;v.innerHTML=`<div class="section-head"><div><h2>Risk Alert Queue</h2></div><span class="badge ${d.count?'warn':'good'}">${d.count} ACTIVE</span></div>${d.alerts.length?`<section class="panel">${d.alerts.map(a=>`<div class="alert-row"><span class="alert-sev">${esc(a.severity)}</span><div><div class="alert-title"><b>${esc(a.ticker)}</b> · ${esc(a.title)}</div><div class="alert-body">${esc(a.body)}</div></div><b class="${clsRisk(a.risk_score||0)}">${a.risk_score??'—'}</b></div>`).join('')}</section>`:'<div class="empty">No WATCH-or-higher portfolio alerts at this time.</div>'}<p class="updated" style="margin-top:8px">Updated ${timeText(d.updated_at)}</p>`}catch(e){if(viewActive(viewSeq))v.innerHTML=errorBox(e)}}

async function Settings(){setTitle('Settings','Data, scanner and optional local-AI configuration');let v=$('#view'),viewSeq=renderGeneration;v.innerHTML=loading('Loading settings…');try{let s=await api('/api/settings');if(!viewActive(viewSeq))return;v.innerHTML=`<form id="settingsForm"><div class="settings-layout"><section class="panel setting-group"><h3>Scanner</h3><label>Hunter max symbols<input id="hm" type="number" min="5" max="100" value="${s.hunter_max_symbols}"></label><label>Custom Hunter universe<textarea id="hu" placeholder="Blank = built-in universe. Otherwise comma-separated tickers.">${esc(s.hunter_universe||'')}</textarea></label></section><section class="panel setting-group"><h3>Optional AI</h3><p>Core research works without AI.</p><label>AI enhancement<select id="oe"><option value="false">OFF — Core Research only</option><option value="true">ON — Add Ollama interpretation</option></select></label><label>Ollama URL<input id="ou" value="${esc(s.ollama_url)}"></label><label>Ollama model<select id="om"><option value="auto">auto</option>${s.ollama_model&&s.ollama_model!=='auto'?`<option value="${esc(s.ollama_model)}">${esc(s.ollama_model)}</option>`:''}</select></label><div class="toolbar"><button class="secondary" type="button" id="testOllama">TEST / LOAD MODELS</button><span id="ollamaStatus" class="tiny"></span></div></section><section class="panel setting-group"><h3>SEC access</h3><label>SEC User-Agent<input id="su" value="${esc(s.sec_user_agent)}"><small>Recommended format: StonkResearch/0.5 your-email@example.com</small></label></section><section class="panel setting-group update-settings"><h3>Application Updates</h3><p>Verified updates · approval required</p><div class="tiny" id="updateStatus">Checking updater status…</div><div class="tiny" id="updateDetails"></div><progress id="updateProgress" max="100" value="0" style="display:none;width:100%;margin-top:8px"></progress><div class="toolbar" style="margin-top:12px"><button class="secondary" type="button" id="checkUpdates">CHECK FOR UPDATES</button><button class="primary" type="button" id="downloadUpdate" style="display:none">DOWNLOAD &amp; VERIFY</button><button class="primary" type="button" id="applyUpdate" style="display:none">RESTART TO INSTALL</button></div><p class="tiny" id="previousUpdateResult"></p></section></div><div class="toolbar" style="margin-top:12px"><button class="primary" type="submit">SAVE SETTINGS</button><span id="saved" class="saved"></span></div><div id="settingsErr"></div></form><div class="settings-foot">${fold('Data and privacy','<p>Free Yahoo/SEC/news sources may be delayed or unavailable. Ollama is optional. Portfolio data stays local. No automatic trading.</p>')}</div>`;bindUpdateControls();refreshUpdateState();if(settingsFocusUpdates){settingsFocusUpdates=false;$('#updateStatus')?.scrollIntoView?.({behavior:'smooth',block:'center'})}$('#oe').value=String(s.ollama_enabled);$('#om').value=s.ollama_model||'auto';$('#testOllama').onclick=async()=>{let b=$('#testOllama'),st=$('#ollamaStatus');b.disabled=true;st.textContent='Checking…';try{let d=await api('/api/ollama/status');if(!viewActive(viewSeq))return;let sel=$('#om'),cur=sel.value;sel.innerHTML='<option value="auto">auto</option>'+(d.models||[]).map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join('');if([...sel.options].some(o=>o.value===cur))sel.value=cur;st.textContent=d.available?`Connected · ${d.models.length} model(s)`:'Not reachable / no local models';st.className=d.available?'tiny good':'tiny warn'}catch(e){st.textContent=e.message;st.className='tiny bad'}finally{b.disabled=false}};$('#settingsForm').onsubmit=async e=>{e.preventDefault();$('#saved').textContent='Saving…';$('#settingsErr').innerHTML='';try{let out=await api('/api/settings',{method:'POST',body:JSON.stringify({ollama_enabled:$('#oe').value==='true',ollama_url:$('#ou').value.trim(),ollama_model:$('#om').value,sec_user_agent:$('#su').value.trim(),hunter_max_symbols:Number($('#hm').value),hunter_universe:$('#hu').value.trim()})});if(!viewActive(viewSeq))return;$('#hm').value=out.hunter_max_symbols;$('#oe').value=String(out.ollama_enabled);$('#saved').textContent='Saved ✓';setTimeout(()=>{if($('#saved'))$('#saved').textContent=''},1800)}catch(x){if(!viewActive(viewSeq))return;$('#saved').textContent='';$('#settingsErr').innerHTML=errorBox(x)}}}catch(e){if(viewActive(viewSeq))v.innerHTML=errorBox(e)}}
function render(auto=false){
  ++renderGeneration;workspaceTabs();
  if(page==='Market')return marketTab==='Overview'?Market():News();
  if(page==='Discover')return Hunter(auto);
  if(page==='Research')return DeepResearch();
  if(page==='Portfolio')return portfolioTab==='Holdings'?Portfolio():portfolioTab==='Risk Monitor'?Risk():Alerts();
  if(page==='Settings')return Settings();
}
function heartbeat(){fetch('/api/ping',{cache:'no-store'}).catch(()=>{})}
shell();$('#globalSearch').onsubmit=e=>{e.preventDefault();let t=$('#globalTicker').value.trim().toUpperCase();if(!t)return;openResearchTicker(t,page)};document.addEventListener('keydown',e=>{let tag=document.activeElement?.tagName;if(e.key==='Escape'&&page==='Research'&&researchDetailActive&&!['INPUT','TEXTAREA','SELECT'].includes(tag))returnFromResearch()});heartbeat();setInterval(heartbeat,4000);render();startUpdateChecks();
